<script lang="ts">
  import { onDestroy, onMount } from 'svelte';
  import { Terminal } from '@xterm/xterm';
  import '@xterm/xterm/css/xterm.css';
  import { CodexTerminalClient, type TerminalChunk } from '../lib/codexTerminalClient.ts';
  import type { RuntimeRecord } from '../lib/model/entityTypes.ts';
  export let runtime:RuntimeRecord|null=null;
  /** Exact Phase 5 Run lifecycle for display; raw process facts remain controls/evidence only. */
  export let lifecycle='UNKNOWN';
  export let onStop:(runId:string)=>Promise<unknown>|unknown=()=>{};
  export let onResume:(runId:string)=>Promise<unknown>|unknown=()=>{};
  export let stopPending=false;
  export let resumePending=false;
  let terminalHost:HTMLDivElement,terminal:Terminal|null=null,client:CodexTerminalClient|null=null,connectedRunId:string|null=null,terminalViewport:HTMLElement|undefined;
  let autoScroll=true,fullscreen=false,streamError=false,terminalReady=false;
  $: if(terminalReady&&runtime?.runId!==connectedRunId)connectRuntime(runtime);
  $: live=runtime?.processAlive===true||runtime?.pidAlive===true;
  $: terminalStatus=!runtime?'NO RUN':live?'LIVE':lifecycle==='FAILED'?'FAILED':lifecycle==='UNKNOWN'?'UNKNOWN':'EXITED';
  $: duration=formatDuration(runtime?.startedAt,runtime?.completedAt??(live?undefined:runtime?.lastActivityAt));
  $: resumableRuntime=runtime as (RuntimeRecord & {stopRequested?:boolean;stopReason?:string;controlLoopId?:string})|null;
  $: resumeReason=!runtime?'NO_RUNTIME_SELECTED':runtime.phase==='STOPPED'&&resumableRuntime?.stopRequested===true&&Boolean(runtime.instructionText)?'':runtime.phase==='STOPPED'?'RESUME_CONTEXT_MISSING':runtime.phase==='COMPLETED'?'ALREADY_COMPLETED':runtime.phase==='FAILED'?'RESUME_NOT_AVAILABLE_FOR_FAILED_RUN':'RUN_STILL_RUNNING';
  $: resumeEnabled=Boolean(runtime&&resumeReason==='');
  $: stopEnabled=Boolean(runtime&&['STARTING','RUNNING'].includes(runtime.phase)&&(runtime.processAlive===true||runtime.pidAlive===true));
  $: stopReason=!runtime?'NO_RUNTIME_SELECTED':stopEnabled?'':'PROCESS_NOT_RUNNING';
  onMount(()=>{terminal=new Terminal({convertEol:false,disableStdin:true,scrollback:10_000,fontFamily:'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace',fontSize:12,theme:{background:'#10151d',foreground:'#d9e2ef',cursor:'#d9e2ef',selectionBackground:'#36506b'}});terminal.open(terminalHost);terminalReady=true;terminalViewport=terminalHost.querySelector('.xterm-viewport')??undefined;terminalViewport?.addEventListener('scroll',onTerminalScroll,{passive:true});connectRuntime(runtime)});
  onDestroy(()=>{terminalViewport?.removeEventListener('scroll',onTerminalScroll);client?.disconnect();terminal?.dispose()});
  function connectRuntime(next:RuntimeRecord|null){client?.disconnect();client=null;connectedRunId=next?.runId??null;streamError=false;if(!next?.runId||!terminal)return;terminal.reset();client=new CodexTerminalClient();client.connect(next.runId,{onChunk:chunk=>writeChunk(chunk),onClose:()=>streamError=false,onError:()=>streamError=true})}
  function writeChunk(chunk:TerminalChunk){if(chunk.runId!==connectedRunId||!terminal)return;terminal.write(chunk.data);if(autoScroll)requestAnimationFrame(()=>terminal?.scrollToBottom())}
  function onTerminalScroll(){if(!terminalViewport||!autoScroll)return;if(terminalViewport.scrollHeight-terminalViewport.scrollTop-terminalViewport.clientHeight>8)autoScroll=false}
  function setAutoScroll(value:boolean){autoScroll=value;if(value)requestAnimationFrame(()=>terminal?.scrollToBottom())}
  function clearBrowserView(){terminal?.reset()}
  function formatDuration(start?:string,end?:string){if(!start)return '不可用';const from=Date.parse(start),to=end?Date.parse(end):Date.now();if(!Number.isFinite(from)||!Number.isFinite(to))return '不可用';const seconds=Math.max(0,Math.floor((to-from)/1000));return `${Math.floor(seconds/60)}分${String(seconds%60).padStart(2,'0')}秒`}
</script>
<section class:fullscreen class="codex-cli-live" data-testid="codex-cli-live" data-run-id={runtime?.runId??'none'}>
  <div class="codex-cli-live-body">
    <div class="codex-cli-info"><div class="codex-cli-live-header"><div><strong>Codex CLI Live</strong><small>same real PTY stream</small></div><b class:live={terminalStatus==='LIVE'} class:failed={terminalStatus==='FAILED'}><i></i>{terminalStatus}</b></div>{#if runtime}<dl class="codex-cli-metadata"><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">PID</dt><dd class="codex-cli-metadata-value">{runtime.pid??'不可用'}</dd></div><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">运行时长</dt><dd class="codex-cli-metadata-value">{duration}</dd></div><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">启动时间</dt><dd class="codex-cli-metadata-value">{runtime.startedAt??'不可用'}</dd></div><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">模型</dt><dd class="codex-cli-metadata-value">{runtime.resolvedModel??runtime.requestedModel??runtime.model??'不可用'}</dd></div><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">推理级别</dt><dd class="codex-cli-metadata-value">{runtime.reasoningLevel??'不可用'}</dd></div><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">退出码</dt><dd class="codex-cli-metadata-value">{runtime.exitCode??'—'}</dd></div><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">可执行文件</dt><dd class="codex-cli-metadata-value">{runtime.spawnExecutable??'不可用'}</dd></div><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">工作目录</dt><dd class="codex-cli-metadata-value">{runtime.spawnCwd??runtime.worktreePath??'不可用'}</dd></div><div class="codex-cli-metadata-row"><dt class="codex-cli-metadata-label">会话 ID / PTY</dt><dd class="codex-cli-metadata-value">{runtime.ptySessionId??'不可用'}</dd></div></dl>{:else}<p class="codex-cli-empty">NO RUN · 当前 Task 没有 Runtime / PTY 证据。</p>{/if}</div>
  <div class="codex-cli-terminal-pane"><div class="codex-terminal-shell" aria-label="Codex CLI real terminal output"><div bind:this={terminalHost} class="codex-terminal"></div>{#if !runtime}<div class="codex-terminal-empty">NO TERMINAL EVIDENCE</div>{:else if streamError}<div class="codex-terminal-note">Terminal stream temporarily unavailable; canonical runtime evidence remains unchanged.</div>{/if}</div><div class="codex-cli-controls"><button type="button" class:active={autoScroll} onclick={()=>setAutoScroll(!autoScroll)}>自动滚动 {autoScroll?'ON':'OFF'}</button><span></span><button type="button" class="continue-action" data-testid="codex-cli-continue" disabled={!resumeEnabled||resumePending} title={resumePending?'RESUME_IN_FLIGHT':resumeReason||'可基于 exact stopped runtime 创建新的 execution'} onclick={()=>{const runId=runtime?.runId;if(runId)void onResume(runId)}}>{resumePending?'继续中…':'继续'}</button><button type="button" class="stop-action" data-testid="codex-cli-stop" disabled={!stopEnabled||stopPending} title={stopPending?'STOP_IN_FLIGHT':stopReason||'可停止当前 managed process'} onclick={()=>{const runId=runtime?.runId;if(runId)void onStop(runId)}}>{stopPending?'停止中…':'停止'}</button><button type="button" onclick={clearBrowserView}>清屏</button><button type="button" onclick={()=>fullscreen=!fullscreen}>{fullscreen?'退出全屏':'全屏'}</button></div></div>
  </div>
</section>
<style>
  .codex-cli-controls button:disabled{background:#e2e8f0;color:#94a3b8;border-color:#cbd5e1;cursor:not-allowed;opacity:1}
  .codex-cli-live{width:100%;max-width:none;min-width:0;container-type:inline-size}.codex-cli-live.fullscreen{position:fixed;z-index:50;inset:18px;padding:16px;border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface);box-shadow:0 18px 50px rgba(15,23,42,.32)}.codex-cli-live-body{display:grid;grid-template-columns:minmax(220px,.3fr) minmax(0,.7fr);align-items:stretch;gap:14px;min-width:0}.codex-cli-info,.codex-cli-terminal-pane{display:grid;min-width:0;gap:10px}.codex-cli-info{align-content:start;padding:12px;border:1px solid var(--border-soft);border-radius:7px;background:var(--surface-soft)}.codex-cli-live-header{display:flex;align-items:center;justify-content:space-between;gap:10px}.codex-cli-live-header strong{display:block;font-size:14px}.codex-cli-live-header small{display:block;margin-top:2px;color:var(--text-3);font:10px var(--font-tech)}.codex-cli-live-header b{display:flex;align-items:center;gap:5px;font:600 11px var(--font-tech);color:var(--text-3)}.codex-cli-live-header b i{width:7px;height:7px;border-radius:50%;background:#64748b}.codex-cli-live-header b.live{color:var(--positive)}.codex-cli-live-header b.live i{background:var(--positive)}.codex-cli-live-header b.failed{color:var(--danger)}.codex-cli-live-header b.failed i{background:var(--danger)}.codex-cli-metadata{display:grid;gap:6px;margin:0}.codex-cli-metadata-row{display:grid;grid-template-columns:max-content minmax(0,1fr);align-items:center;column-gap:12px;min-width:0}.codex-cli-metadata-label{color:var(--text-3);text-align:left;white-space:nowrap;font-size:10px}.codex-cli-metadata-value{min-width:0;margin:0;overflow:hidden;color:var(--text-1);text-align:right;text-overflow:ellipsis;white-space:nowrap;font:11px var(--font-tech)}.codex-cli-empty{margin:0;color:var(--text-2);font-size:12px}.codex-terminal-shell{position:relative;min-height:300px;border:1px solid #1d2b3a;border-radius:7px;background:#10151d;overflow:hidden}.fullscreen .codex-terminal-shell{min-height:0;height:calc(100vh - 120px)}.codex-terminal{height:300px;padding:8px;box-sizing:border-box}.fullscreen .codex-terminal{height:100%}.codex-terminal-empty,.codex-terminal-note{position:absolute;inset:0;display:grid;place-items:center;padding:16px;color:#8294ab;font:11px var(--font-tech);pointer-events:none}.codex-terminal-note{place-items:end start;color:#eab86a}.codex-cli-controls{display:flex;align-items:center;gap:6px}.codex-cli-controls span{flex:1}.codex-cli-controls button{min-height:30px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface-soft);color:var(--text-2);font:11px var(--font-ui);cursor:pointer}.codex-cli-controls button.active{border-color:var(--accent);color:var(--accent-ink)}.codex-cli-controls button.stop-action{border-color:var(--danger);color:var(--danger)}@container(max-width:760px){.codex-cli-live-body{grid-template-columns:1fr}.codex-terminal-shell,.codex-terminal{min-height:260px;height:260px}}</style>
